    },
    {
      "text": "The feeder 308639 shows the same fixed small-amount sets toward multiple counterparties, suggesting a scripted rather than organic payment pattern.",
      "citations": ["call_01_8c0IPhgaa1Nwk1SZufbr3281"]
    }
  ],
